"""Checked, lossless manager transport only. No AI calls or service changes."""
import argparse,base64,fcntl,hashlib,importlib,importlib.util,json,os,sys,tempfile,time
from pathlib import Path
FILES = {'remembered_products_packing.py': '', 'manager_practice_bridge.py': '', 'manager_remembered_runtime.py': ''}
PREVIOUS = {'remembered_products_packing.py': 'f9547f950759ba9a78df3033830140d07267ca487ac54cffce204ad76f9ee1e0', 'manager_practice_bridge.py': '7329219ed847a099cbaf52093cbeef7eee2eafe645d2849c6917b6aa6cb1027a', 'manager_remembered_runtime.py': '2e2cebfc528c3a48ee8e11ff6747646a2be2af5720454c0db07fc5b49bd4f285'}

def sha(raw):return hashlib.sha256(raw).hexdigest()
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def write_atomic(p,raw):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.transport-')
    try:
        with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        os.replace(name,p)
    finally:
        if os.path.exists(name):os.unlink(name)

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--root',type=Path,default=Path('/home/ubuntu'));parser.add_argument('--apply',action='store_true');args=parser.parse_args()
    os.umask(0o077)
    root=args.root.resolve();state=root/'dj-manager-memory/runtime'
    active=read(state/'ACTIVATED.json');code=Path(active['code']).resolve()
    code.relative_to((root/'dj-manager-memory/runtime-code').resolve())
    release=Path(active.get('release') or root/'dj-manager-memory/releases/20261004_203930')
    payload={n:base64.b64decode(v) for n,v in FILES.items()}
    originals={}
    for n,raw in payload.items():
        compile(raw,str(code/n),'exec')
        p=code/n
        if p.is_symlink():raise ValueError('코드 링크 경로 적용 중단')
        old=p.read_bytes();originals[n]=old
        if old!=raw and sha(old)!=PREVIOUS[n]:raise ValueError('예상과 다른 기존 코드: '+n+' · 변경 없음')
    with (state/'worker.lock').open('a') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise SystemExit('기존 작업 실행 중. 변경·AI 요청 없음')
        sys.path.insert(0,str(code))
        inputs=importlib.import_module('manager_memory_inputs')
        rt=importlib.import_module('manager_remembered_runtime')
        retrieval=importlib.import_module('manager_memory_retrieval')
        if retrieval.POLICY!='preserved-paper-and-live-v2':raise ValueError('기억 연결 버전 확인 필요')
        # New code is loaded only in this process for capacity checks.
        with tempfile.TemporaryDirectory(prefix='manager-transport-check-') as tmp:
            temp=Path(tmp)
            for n,raw in payload.items():(temp/n).write_bytes(raw)
            spec=importlib.util.spec_from_file_location('remembered_products_packing',temp/'remembered_products_packing.py')
            packing=importlib.util.module_from_spec(spec);spec.loader.exec_module(packing)
            sys.modules['remembered_products_packing']=packing
            spec=importlib.util.spec_from_file_location('manager_practice_bridge',temp/'manager_practice_bridge.py')
            bridge=importlib.util.module_from_spec(spec);spec.loader.exec_module(bridge)
            # Original source remains in active code, verified by its own manifest.
            bridge.originals.__wrapped__.__globals__['__file__']=str(code/'manager_practice_bridge.py')
            rt.wire_text=packing.wire_text
            pool=inputs.load_pool(root)['pool'];report={'AI_requests':0,'files_changed':False,'limit':rt.MAX_CHARS,'matches':len(pool),'analysts':{}}
            if not pool:raise ValueError('예정 경기 없음. 실제 용량 검증 후 적용 필요')
            _,practice,remembered=bridge.originals()
            # Verify adapter construction without constructing client or making requests.
            for cls in (practice.PracticeAuthor,remembered.RememberedAuthor):
                bridge.attach_lossless_transport(cls.__new__(cls))
            fits=True
            for engine in inputs.ENGINES:
                memory=rt.append_live_memory(inputs.load_memory(release,engine,pool),state,engine,pool)
                base={'mode':'candidates','analyst':engine,'memory':memory}
                wrapper_max=native_max=old_max=0
                for q in pool:
                    packet=retrieval.prepare_packet(dict(base,questions=[q]))
                    wrapper_max=max(wrapper_max,len(packing.wire_text(rt.INSTRUCTION,packet)))
                    old_max=max(old_max,len(packing.legacy_wire_text(rt.INSTRUCTION,packet)))
                    outgoing,_,_=bridge.exam_packet(packet)
                    native_max=max(native_max,len(packing.wire_text(remembered.MEMORY_INSTRUCTIONS,outgoing)))
                report['analysts'][engine]={'previous_max_chars':old_max,'new_max_chars':wrapper_max,'paper_request_max_chars':native_max,'paper_successes':len(memory['successful_memory']),'paper_errors':len(memory['error_memory']),'live_reviews':len(memory.get('live_pick_reviews',[]))}
                fits=fits and native_max<=800_000
            report['capacity_check']='PASS' if fits else 'BLOCKED';print(json.dumps(report,ensure_ascii=False,indent=2),flush=True)
            if not fits:raise SystemExit('용량 검증 미통과. 코드 적용·기억 삭제·AI 요청 없음')
        if not args.apply:return
        if read(state/'ACTIVATED.json')!=active:raise ValueError('활성 코드 경로 변경. 적용 중단')
        for n,old in originals.items():
            if (code/n).read_bytes()!=old:raise ValueError('검증 중 코드 변경. 적용 중단')
        changed=[n for n in payload if payload[n]!=originals[n]]
        if not changed:print('ALREADY_INSTALLED · AI 요청 없음');return
        backup=state/'deployments'/('lossless-transport-'+str(time.time_ns()));backup.mkdir(parents=True)
        for n in changed:(backup/n).write_bytes(originals[n])
        (backup/'verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
        done=[]
        try:
            for n in changed:write_atomic(code/n,payload[n]);done.append(n)
        except BaseException:
            for n in done:write_atomic(code/n,originals[n])
            raise
        print('TRANSPORT_INSTALLED · 백업: '+str(backup)+' · AI 요청·서비스 재시작 없음')

if __name__=='__main__':main()
